  async function emptyForum(page: Page): Promise<void> {
    await page.route(/\/messages(?:\?|$)/, async (route) => {
      if (route.request().method() !== 'GET') {
        await route.continue();
        return;
      }
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ messages: [] }),
      });
    });
  }

  async function stubComposeInvoice(page: Page, sparkInvoice?: string): Promise<void> {
    await page.route('**/messages/compose-target', async (route) => {
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ messageId: 'compose-fee', sats: 0 }),
      });
    });
    await page.route(/\/messages\/compose-fee\/invoice$/, async (route) => {
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify(
          sparkInvoice === undefined
            ? { pr: 'lnbc1test', amountSats: 1 }
            : { pr: 'lnbc1test', amountSats: 1, sparkInvoice },
        ),
      });
    });
  }

