const HABIT_ROW = {
  id: 'h-ada',
  accountId: 'acc-ada',
  ownerName: 'Ada',
  role: 'initiator',
  name: 'Walk',
  description: 'Outside',
  cadence: 'daily',
  timeZone: 'Asia/Manila',
  firstPeriod: '2026-10-01',
  lastPeriod: null,
  periods: [
    {
      period: '2026-10-04',
      name: 'Walk',
      description: 'Outside',
      logged: false,
      status: null,
    },
  ],
  comments: [
    {
      id: 'c-bea',
      habitId: 'h-ada',
      accountId: 'acc-bea',
      name: 'Bea',
      text: 'hello',
      week: '2026-09-28',
      createdAt: 1,
    },
  ],
};

const HABIT_PUBLIC = {
  reviewWeek: { start: '2026-09-28' },
  habits: [HABIT_ROW],
};

async function stubHabitList(page: Page, body: unknown, status = 200): Promise<void> {
  await page.route('**/habits', async (route) => {
    await route.fulfill({
      status,
      contentType: 'application/json',
      body: JSON.stringify(body),
    });
  });
}

async function shotRatedHabit(
  page: Page,
  status: 'achieved' | 'partial' | 'missed',
  buttonName: string,
): Promise<void> {
  await seedHabitAda(page);
  let rated = false;
  await page.route('**/habits', async (route) => {
    if (route.request().method() === 'POST') {
      rated = true;
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ ok: true }),
      });
      return;
    }
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({
        reviewWeek: HABIT_PUBLIC.reviewWeek,
        habits: [
          {
            ...HABIT_ROW,
            accountId: 'acc_e2e',
            notes: 'secret',
            periods: [
              {
                period: '2026-10-04',
                name: 'Walk',
                description: 'Outside',
                logged: rated,
                status: rated ? status : null,
              },
            ],
          },
        ],
      }),
    });
  });
  await page.goto('/habit-tracker');
  const pill = page.getByRole('button', { name: buttonName, exact: true });
  await expect(pill).toHaveAttribute('aria-pressed', 'false');
  await pill.click();
  await expect(pill).toHaveAttribute('aria-pressed', 'true');
  await pill.scrollIntoViewIfNeeded();
}

async function seedHabitAda(page: Page): Promise<void> {
  await page.addInitScript(() => {
    localStorage.setItem('21gifts.session', 'sess-e2e');
  });
  await page.route('**/gifts/stats**', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: '{"spendOverTime":[]}',
    });
  });
  await page.route(/\/me$/, async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({
        ...E2E_ACCOUNT,
        name: 'Ada',
        location: null,
        username: 'alice',
        lightningAddress: 'alice@walletofsatoshi.com',
        rulesAgreedAt: 1_700_000_001,
        viewKey: 'a'.repeat(64),
        aboutMe: null,
        setup: null,
        missing: [],
      }),
    });
  });
}

